// Preparar datos del sitio para enviar al subworkflow
const siteData = $input.item.json;

// Validación básica de datos requeridos
if (!siteData.Sitio_URL || !siteData.WP_API_Key) {
  return {
    json: {
      ...siteData,
      validation_error: true,
      error_message: 'Sitio_URL o WP_API_Key faltante',
      site_domain: siteData.Sitio_URL ? new URL(siteData.Sitio_URL).hostname : 'unknown'
    }
  };
}

const siteDomain = new URL(siteData.Sitio_URL).hostname;

return {
  json: {
    ...siteData,
    site_domain: siteDomain,
    validation_error: false,
    processing_timestamp: new Date().toISOString()
  }
};

// Log de resultado exitoso
const result = $input.item.json;

const logEntry = {
  timestamp: new Date().toISOString(),
  site: result.site_domain || result.Sitio_URL,
  status: 'SUCCESS',
  articles_processed: result.articles_processed || 0,
  file_size: result.file_size || 0,
  insights_generated: result.insights_count || 0,
  upload_status: result.upload_status || 'UNKNOWN',
  execution_time_ms: result.execution_time_ms || 0
};

console.log('✅ Sitio procesado exitosamente:', JSON.stringify(logEntry, null, 2));

return {
  json: logEntry
};

// Log de error o fallo
const result = $input.item.json;
const siteInfo = $input.first().json;

// Detectar si viene del error output del Execute Workflow
const isErrorOutput = result.error !== undefined;

const logEntry = {
  timestamp: new Date().toISOString(),
  site: result.site_domain || siteInfo.site_domain || 'unknown',
  status: 'FAILED',
  error_type: isErrorOutput ? 'SUBWORKFLOW_ERROR' : (result.status || 'UNKNOWN_ERROR'),
  error_message: result.error_message || result.error?.message || 'Error no especificado',
  error_details: {
    validation_error: siteInfo.validation_error || false,
    api_error: result.api_error || false,
    sftp_error: result.sftp_error || false,
    ai_error: result.ai_error || false
  },
  articles_attempted: result.articles_processed || 0
};

console.error('❌ Error procesando sitio:', JSON.stringify(logEntry, null, 2));

return {
  json: logEntry
};

// Log de error de validación (sitio sin datos requeridos)
const siteData = $input.item.json;

const logEntry = {
  timestamp: new Date().toISOString(),
  site: siteData.site_domain || siteData.Sitio_URL || 'unknown',
  status: 'VALIDATION_FAILED',
  error_type: 'MISSING_REQUIRED_DATA',
  error_message: siteData.error_message || 'Datos requeridos faltantes',
  missing_fields: [
    !siteData.Sitio_URL ? 'Sitio_URL' : null,
    !siteData.WP_API_Key ? 'WP_API_Key' : null,
    !siteData.sFTP_Host ? 'sFTP_Host' : null,
    !siteData.sFTP_User ? 'sFTP_User' : null,
    !siteData.sFTP_Pass ? 'sFTP_Pass' : null
  ].filter(f => f !== null)
};

console.error('⚠️ Validación fallida:', JSON.stringify(logEntry, null, 2));

return {
  json: logEntry
};

// Generar reporte consolidado final
const allResults = $input.all().map(item => item.json);

// Agrupar por status
const successResults = allResults.filter(r => r.status === 'SUCCESS');
const failedResults = allResults.filter(r => r.status === 'FAILED');
const validationFailedResults = allResults.filter(r => r.status === 'VALIDATION_FAILED');
const skippedResults = allResults.filter(r => r.status === 'SKIPPED');

// Estadísticas
const totalArticlesProcessed = successResults.reduce((sum, r) => sum + (r.articles_processed || 0), 0);
const totalFileSize = successResults.reduce((sum, r) => sum + (r.file_size || 0), 0);
const avgExecutionTime = successResults.length > 0 
  ? successResults.reduce((sum, r) => sum + (r.execution_time_ms || 0), 0) / successResults.length 
  : 0;

// Agrupar errores por tipo
const errorsByType = failedResults.reduce((acc, r) => {
  const errorType = r.error_type || 'UNKNOWN';
  acc[errorType] = (acc[errorType] || 0) + 1;
  return acc;
}, {});

const summary = {
  execution_timestamp: new Date().toISOString(),
  total_sites_in_config: allResults.length,
  successful_uploads: successResults.length,
  failed_sites: failedResults.length,
  validation_failed: validationFailedResults.length,
  skipped_sites: skippedResults.length,
  total_articles_processed: totalArticlesProcessed,
  total_file_size_bytes: totalFileSize,
  avg_execution_time_ms: Math.round(avgExecutionTime),
  success_rate: ((successResults.length / allResults.length) * 100).toFixed(2) + '%',
  errors_by_type: errorsByType,
  detailed_results: allResults
};

// Log resumen ejecutivo
const executiveSummary = `
╔════════════════════════════════════════════════════════════╗
║           REPORTE FINAL - LLMS.txt Auto-Updater           ║
╚════════════════════════════════════════════════════════════╝

📊 RESUMEN EJECUTIVO:
  • Total de sitios: ${allResults.length}
  • ✅ Exitosos: ${successResults.length}
  • ❌ Fallidos: ${failedResults.length}
  • ⚠️  Validación fallida: ${validationFailedResults.length}
  • ⏭️  Omitidos: ${skippedResults.length}
  • 📈 Tasa de éxito: ${summary.success_rate}

📝 PROCESAMIENTO:
  • Total artículos procesados: ${totalArticlesProcessed}
  • Tamaño total archivos: ${(totalFileSize / 1024).toFixed(2)} KB
  • Tiempo promedio por sitio: ${Math.round(avgExecutionTime / 1000)}s

❌ ERRORES (si los hay):
${Object.entries(errorsByType).map(([type, count]) => `  • ${type}: ${count} sitio(s)`).join('\n') || '  • Sin errores'}

⏰ Ejecutado: ${new Date().toLocaleString()}
`;

console.log(executiveSummary);

return {
  json: summary
};
